src={(2,5),(3,3),(3,4),(3,5),(3,7),(4,3),(5,3),(5,4),(5,5),(5,6),(6,2),(6,6)}
out={(2,5),(3,2),(3,3),(4,3),(4,5),(4,6),(5,3),(5,5),(6,3),(6,4),(6,5),(7,2)}
# transformations mapping 9x10 src to 10x9
transforms={
'cw': lambda r,c:(c,8-r),
'ccw':lambda r,c:(9-c,r),
'flip_h':lambda r,c:(r,9-c),
'flip_v':lambda r,c:(8-r,c),
'transpose':lambda r,c:(c,r),
'anti':lambda r,c:(9-c,8-r),
}
for n,f in transforms.items():
 s={f(*x) for x in src}
 print(n,s==out, s ^ out)
